import numpy as np

def solve_pattern(input_grid):
    rows, cols = len(input_grid), len(input_grid[0])
    result = np.zeros((rows, cols), dtype=int)

    # Find all non-zero cells
    origins = []
    for i in range(rows):
        for j in range(cols):
            if input_grid[i][j] != 0:
                origins.append((i, j, input_grid[i][j]))

    # For each origin, place anchors at Manhattan distance 4N from origin
    # in cardinal directions, then fill 3x3 diamond with 5s
    for r, c, n in origins:
        for d in [(-1,0), (1,0), (0,-1), (0,1)]:  # Up, down, left, right
            nr, nc = r + d[0] * 4 * n, c + d[1] * 4 * n
            if 0 <= nr < rows and 0 <= nc < cols:
                # Place anchor
                if input_grid[r][c] == n:
                    result[nr][nc] = n
                else:
                    # Multiple numbers might map here - keeps the one that projects here
                    if input_grid[r][c] == 1:
                        result[nr][nc] = 1  # 1 extends vertically
                    elif input_grid[r][c] == 2:
                        result[nr][nc] = 2  # 2 extends horizontally
                    elif input_grid[r][c] == 3:
                        result[nr][nc] = 3  # 3 extends horizontally  
                    result[r][c] = n  # Keep original

    return result

# Test input
test_input = [
