# Try a simpler pattern based on all demos
# Pattern: anchors at distance 4 in cardinal directions from each origin
# 5s fill the 3x3 diamond centered at each anchor
# Preserve original numbers

def apply_pattern(ip):
    result = np.array(ip)
    ro, co = result.shape

    origins = []
    for i in range(ro):
        for j in range(co):
            if result[i][j] != 0:
                origins.append((i, j, result[i][j]))

    for r, c, n in origins:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            ar, ac = r + dr * 4 * n, c + dc * 4 * n
            if 0 <= ar < ro and 0 <= ac < co:
                result[ar][ac] = n
                # Fill 3x3 with 5s
                for i in range(max(0, ar-2), min(ro, ar+3)):
                    for j in range(max(0, ac-2), min(co, ac+3)):
                        if result[i][j] == 0:
                            result[i][j] = 5
                # Keep special numbers (1,2,3,6) from their anchors
                result[r][c] = n

    return result

output = apply_pattern(test_input)
